"""Complete 28 original spondyloarthritis questions."""
from create_rheum_spa import rows,q,S,K,P,D,ref
from qbank_authoring import finalize

q('A patient has persistent asymmetric peripheral knee and ankle synovitis associated with SpA, but no active axial symptoms. Which conventional DMARD may be considered for the peripheral arthritis?', 'Sulfasalazine',[
 ('Hydroxychloroquine as a proven treatment for sacroiliitis','It is not established axial treatment and does not address the stated evidence base.'),('Allopurinol','It treats urate excess, not noncrystal SpA synovitis.'),('Alendronate','It is an osteoporosis medication rather than a DMARD for peripheral synovitis.')],
 'Peripheral arthritis is a different treatment domain','**Sulfasalazine can be considered for peripheral SpA arthritis.**',['Its possible benefit for peripheral joints should not be extrapolated to pure axial disease.','The precise strategy depends on whether the phenotype is psoriatic, reactive or bowel-associated and on severity.'], '**Confirm the inflamed structure and exclude infection or crystals when needed.**',['Consider local measures for limited disease.','Escalate according to response, prognostic factors and the associated disease domains.'],[['Peripheral synovitis','csDMARD may have a role'],['Pure axial disease','csDMARD benefit is not established'],['Associated psoriasis/IBD','Affects drug choice']],[S,K])

q('A patient with psoriasis, nail dystrophy and persistent polyarticular peripheral PsA needs a conventional DMARD. Which option is generally favored when the skin disease is clinically relevant?', 'Methotrexate',[
 ('Hydroxychloroquine','It is not the usual preferred csDMARD for this PsA scenario and can raise psoriasis concerns.'),('Azathioprine','It is not the usual first csDMARD strategy for peripheral PsA.'),('Cyclophosphamide','Its risk profile and indications do not fit routine peripheral PsA treatment.')],
 'Start a peripheral disease-modifying strategy promptly','**Methotrexate is a common preferred csDMARD when peripheral PsA and relevant skin psoriasis coexist.**',['Assess poor prognostic factors, functional impact and number of involved joints.','Predominant axial disease or unequivocal enthesitis may require a different pathway.'], '**Treat to a defined clinical target.**',['Monitor drug toxicity and response rather than continuing an ineffective regimen indefinitely.','Escalation to an advanced agent depends on the active domains and comorbidities.'],[['Peripheral arthritis plus skin disease','Methotrexate often useful'],['Axial disease','Different evidence base'],['Persistent activity','Adjust treatment']],[P],style='clinical_scenario')

q('An adult with inflammatory arthritis has current psoriasis and a documented history of dactylitis. How many CASPAR points do those two features supply?', '3 points',[
 ('2 points','Current psoriasis supplies two points and documented dactylitis supplies one.'),('4 points','The history of dactylitis does not supply two points.'),('5 points','Additional qualifying features would be needed to reach this number.')],
 'Count features after confirming inflammatory articular disease','**Current psoriasis gives two points and dactylitis gives one.**',['CASPAR requires inflammatory articular disease and at least three points from the defined features.','These are classification criteria rather than a replacement for clinical differential diagnosis.'], '**Do not add current, personal-history and family-history psoriasis points together.**',['Nail dystrophy, RF negativity and defined new bone formation can contribute additional points when present.','A positive RF does not automatically exclude clinical PsA.'],[['Current psoriasis','2 points'],['Dactylitis','1 point'],['Combined','3 points']],[ref('CASPAR original international classification study','https://doi.org/10.1002/art.21972')],style='clinical_scenario')

q('Which statement about a positive rheumatoid factor in a patient with psoriasis and inflammatory arthritis is correct?', 'It does not by itself exclude psoriatic arthritis',[
 ('It establishes rheumatoid arthritis regardless of the joint pattern','A laboratory result must be interpreted with the phenotype.'),('It removes the need to examine nails and entheses','These findings remain important in identifying PsA domains.'),('It is required to meet CASPAR criteria','RF negativity contributes a point, but positivity does not automatically prevent reaching the classification threshold.')],
 'Do not use a single antibody as an exclusion rule','**RA and PsA require clinical pattern recognition, and occasional seropositivity can complicate the distinction.**',['DIP involvement, dactylitis, enthesitis and characteristic bone proliferation support PsA.','Symmetric MCP/wrist synovitis with a compatible serological pattern can support RA.'], '**Consider the possibility of coexisting psoriasis and RA.**',['Use imaging and longitudinal assessment when the presentation is uncertain.','Classify only after establishing inflammatory musculoskeletal disease.'],[['RF positive','Interpret in context'],['PsA features','Dactylitis, enthesitis, nail disease'],['RA phenotype','MCP/wrist synovitis with other supporting evidence']],[ref('CASPAR original international classification study','https://doi.org/10.1002/art.21972')])

q('A patient develops asymmetric lower-limb arthritis and heel enthesitis 3 weeks after diarrheal illness. Synovial culture is negative. Which diagnosis is most likely?', 'Reactive arthritis',[
 ('Septic arthritis due to direct bacterial invasion of every affected joint','The postinfectious timing and sterile inflammatory phenotype favor reactive arthritis, although infection must be excluded when clinically suspected.'),('Rheumatoid arthritis','The lower-limb asymmetric postinfectious enthesitis pattern is less typical of RA.'),('Polymyalgia rheumatica','This usually causes a different age-related shoulder/hip girdle syndrome rather than this presentation.')],
 'Recognize postinfectious sterile inflammation','**Reactive arthritis can follow enteric or genitourinary infection.**',['Enthesitis, dactylitis, conjunctival/uveal disease and mucocutaneous lesions may occur.','The full historical arthritis-urethritis-conjunctivitis triad is not required.'], '**Evaluate active infection and distinguish it from the joint inflammation.**',['Aspirate a severely inflamed joint when septic or crystal arthritis is a concern.','Initial joint treatment often uses NSAIDs and selected local anti-inflammatory measures.'],[['Trigger','Enteric or genitourinary infection'],['Joint pattern','Often asymmetric lower-limb arthritis'],['Synovial culture','Usually sterile in reactive arthritis']],[ref('NHS: reactive arthritis','https://www.nhs.uk/conditions/reactive-arthritis/')],style='clinical_scenario')

q('A patient with reactive arthritis has a positive urine NAAT for Chlamydia trachomatis. Which management principle is correct?', 'Treat the active chlamydial infection and address partners, while separately treating the inflammatory arthritis',[
 ('Use intra-articular steroid alone and leave the infection untreated','Active chlamydia still requires appropriate antimicrobial and public-health management.'),('Assume a standard antibiotic course will reliably cure all chronic joint symptoms','Eradicating active infection does not guarantee immediate resolution of postinfectious arthritis.'),('Give prolonged broad-spectrum antibiotics to every culture-negative postenteric arthritis patient','This is not a routine evidence-based strategy after a resolved enteric infection.')],
 'Separate infection eradication from inflammatory joint care','**Confirmed chlamydia should be treated according to STI guidance.**',['Partner evaluation/treatment and prevention of reinfection are important.','Postinfectious arthritis may persist and require a rheumatological treatment plan.'], '**Tailor antibiotics to the documented infection.**',['Check for other STIs as indicated.','Persistent arthritis warrants reassessment rather than repeated empiric antibiotics without a target.'],[['Active chlamydia','Treat infection and partners'],['Joint inflammation','Separate anti-inflammatory strategy'],['Resolved enteric trigger','Routine prolonged antibiotics not justified']],[ref('CDC: chlamydial infections treatment guidance','https://www.cdc.gov/std/treatment-guidelines/chlamydia.htm'),ref('NHS inform: reactive arthritis','https://www.nhsinform.scot/illnesses-and-conditions/muscle-bone-and-joints/conditions-that-can-affect-multiple-parts-of-the-body/reactive-arthritis')],style='clinical_scenario')

q('Which statement about bowel-associated musculoskeletal disease is most accurate?', 'Axial SpA activity can persist despite control of intestinal inflammation',[
 ('All axial symptoms must resolve whenever endoscopy improves','Axial and bowel activity do not invariably move together.'),('Any arthralgia during IBD proves axial sacroiliitis','Arthralgia, peripheral synovitis, enthesitis and axial disease require distinct assessment.'),('Etanercept reliably treats both Crohn disease and axial SpA','It is not an effective Crohn disease treatment.')],
 'Do not infer spinal activity from the bowel alone','**IBD-associated joint disease has distinct axial and peripheral domains.**',['Some peripheral patterns track bowel inflammation more closely than axial disease.','Treatment should address the domains that are actually active.'], '**Coordinate rheumatology and gastroenterology decisions.**',['Evaluate back pain for inflammatory and mechanical causes.','Select a drug with appropriate efficacy for both conditions when feasible.'],[['Bowel remission','Does not guarantee axial remission'],['Peripheral/axial domains','May behave differently'],['Shared therapy','Requires indication-specific efficacy']],[ref('BSG adult inflammatory bowel disease guideline: 2025','https://gut.bmj.com/content/74/Suppl_2/s1'),S])

q('A patient with a rigid ankylosed spine develops new severe neck pain after a low-energy fall. Initial plain radiographs appear nondiagnostic. What is the priority?', 'Maintain appropriate spinal precautions and obtain urgent CT-based fracture assessment, with MRI when indicated',[
 ('Treat as a simple strain and begin forceful neck manipulation','An ankylosed spine can sustain an unstable fracture after minor trauma.'),('Exclude fracture because the initial radiograph is unrevealing','Plain films can miss clinically important injuries in this setting.'),('Give an NSAID and wait several weeks for repeat films despite severe pain','Delay risks displacement and neurological injury.')],
 'A rigid spine behaves like a long lever arm','**Ankylosis increases the risk of unstable spinal injury after relatively minor trauma.**',['Protect the patient in an appropriate alignment rather than forcibly straightening a fixed deformity.','Additional noncontiguous injuries may require broader imaging.'], '**Use urgent specialist assessment and adequate imaging.**',['CT identifies bony injury; MRI evaluates neural/ligamentous injury when indicated.','A new neurological deficit is an emergency.'],[['Minor trauma','Can cause major injury'],['Plain radiograph','May be insufficient'],['CT/MRI','Define injury and neurological involvement']],[ref('AO Surgery Reference: ankylotic spine injuries','https://surgeryreference.aofoundation.org/spine/trauma/subaxial-cervical/further-reading/ankylotic-spine')],style='clinical_scenario')

q('Which imaging pattern is most consistent with diffuse idiopathic skeletal hyperostosis rather than classic ankylosing spondylitis?', 'Flowing anterolateral ossification across several vertebrae with relative disc preservation and no typical erosive sacroiliitis',[
 ('Thin marginal syndesmophytes with bilateral erosive sacroiliitis','This is more characteristic of radiographic axial SpA.'),('Central DIP erosions with a gull-wing pattern','This is a hand osteoarthritis pattern rather than the spinal distinction.'),('Destructive discitis with adjacent vertebral infection','This suggests infection rather than DISH.')],
 'Distinguish entheseal ossification from inflammatory ankylosis','**DISH commonly produces bulky flowing spinal ligamentous ossification.**',['Age, metabolic context and sacroiliac findings help distinguish it from axial SpA.','Both a DISH-ankylosed and an AS-ankylosed spine can be vulnerable to unstable fractures.'], '**Do not infer inflammatory activity from spinal stiffness alone.**',['Review the pattern of bone formation and other clinical features.','Coexisting degenerative or inflammatory pathology can complicate interpretation.'],[['DISH','Flowing bulky anterolateral ossification'],['AS','Marginal syndesmophytes and sacroiliitis'],['Both','Fracture risk when ankylosed']],[ref('Imaging characteristics of DISH','https://pmc.ncbi.nlm.nih.gov/articles/PMC7046956/')])

q('An adult with axial SpA remains symptomatic despite a biologic, but has no inflammatory markers or imaging evidence of active disease and has widespread mechanical and neuropathic pain. What should precede automatic drug switching?', 'Reassess inflammatory activity, diagnosis, adherence and noninflammatory contributors',[
 ('Assume every symptom is uncontrolled axial inflammation','Structural damage and comorbid pain can persist despite inflammatory control.'),('Add a second biologic to the first without reassessment','This is not a standard safety-conscious response to uncertain disease activity.'),('Use HLA-B27 titers to decide the next dose','HLA-B27 is not a quantitative activity marker.')],
 'Treatment failure is a question to investigate','**Persistent symptoms do not always mean persistent inflammatory disease.**',['Assess drug exposure/adherence and the original diagnosis.','Consider fractures, degenerative disease, fibromyalgia, depression and other comorbidities as indicated.'], '**Switch mechanisms when active disease and a genuine inadequate response are established.**',['Use shared decisions and phenotype-specific options.','Do not let a normal CRP alone exclude activity when clinical evidence remains convincing.'],[['Residual symptoms','Inflammatory or noninflammatory'],['Objective assessment','Supports the escalation decision'],['Confirmed active failure','Consider a different advanced agent']],[S,K],style='clinical_scenario')

q('Which finding is most characteristic of chronic axial SpA-related restriction rather than isolated lumbar muscle strain?', 'Reduced spinal mobility with restricted chest expansion and sacroiliac structural disease',[
 ('Transient paraspinal tenderness after lifting with normal mobility when pain settles','This is more consistent with a mechanical strain.'),('Dermatomal leg pain with a positive straight-leg raise','This suggests radicular irritation.'),('Pain relieved by sitting with posture-dependent neurogenic claudication','This favors spinal stenosis.')],
 'Examine the axial skeleton beyond the painful site','**Axial SpA can restrict spinal and costovertebral movement.**',['Mobility limitation reflects a mixture of inflammation, structural change and other factors.','A normal early examination does not exclude nonradiographic disease.'], '**Document function and mobility over time.**',['Adapt exercise to structural limitations and fracture risk.','Do not use a single bedside mobility test as a definitive diagnostic test.'],[['Chest expansion','May be restricted'],['Lumbar mobility','Assess with standardized measures'],['Early disease','Examination may still be near normal']],[K,ref('ASAS handbook: clinical assessment and classification','https://www.asas-group.org/wp-content/uploads/2020/07/ASAS-handbook.pdf')])

q('A patient with predominant painful heel enthesitis and PsA has no response to appropriate local measures and NSAIDs. Ultrasound supports inflammatory enthesitis. Which escalation is most appropriate?', 'Consider an effective biologic DMARD based on the complete disease phenotype',[
 ('Require methotrexate failure as a proven enthesitis treatment in every patient','Conventional DMARD efficacy is limited for this specific domain; the treatment pathway differs from peripheral synovitis.'),('Inject glucocorticoid directly into the Achilles tendon as the routine next step','Intratendinous injection carries injury/rupture concerns and is not the recommended systemic escalation strategy.'),('Use allopurinol without evidence of urate deposition','This does not treat noncrystal inflammatory enthesitis.')],
 'Confirm unequivocal inflammation before treating the enthesitis domain','**Biologic therapy can be considered for persistent unequivocal PsA enthesitis after appropriate initial measures.**',['Mechanical tendon pain and widespread pain amplification are important mimics.','Skin, bowel, eye and joint manifestations affect drug selection.'], '**Avoid exposing a mechanical tendinopathy to unnecessary immunosuppression.**',['Use targeted imaging when clinical uncertainty remains.','Local injection decisions must respect tendon anatomy and safety.'],[['Confirmed enthesitis','Domain-based treatment'],['Mechanical pain','Load and rehabilitation assessment'],['Biologic choice','Whole-phenotype decision']],[P],style='clinical_scenario')

q('A patient with axial SpA has sustained remission on a biologic and wishes to reduce treatment. Which approach is most appropriate?', 'Consider cautious tapering or dose spacing with monitoring rather than abrupt unmonitored withdrawal',[
 ('Stop all therapy abruptly because remission proves cure','Disease may flare after treatment withdrawal.'),('Continue unchanged indefinitely regardless of recurrent serious toxicity','Safety events require reassessment and individualized decisions.'),('Replace the biologic with methotrexate as an equivalently proven axial maintenance therapy','Methotrexate does not have equivalent evidence for isolated axial disease.')],
 'Reduce exposure without abandoning disease surveillance','**Sustained remission can permit a shared discussion about tapering.**',['Dose spacing or reduction is distinct from immediate complete cessation.','Consider duration of control, prior relapse, comorbidities and patient preferences.'], '**Specify how activity will be monitored and managed if it returns.**',['Reassess symptoms and objective activity at appropriate intervals.','A taper is not a guarantee that treatment can be permanently stopped.'],[['Sustained remission','Possible taper discussion'],['Abrupt withdrawal','Higher flare concern'],['Follow-up plan','Detect and treat recurrence']],[S,K],style='clinical_scenario')

q('Which pair of clinical features most strongly supports a peripheral SpA pattern over classic RA?', 'Asymmetric lower-limb oligoarthritis with enthesitis',[
 ('Symmetric MCP and wrist synovitis with high-positive ACPA','This more strongly supports an RA phenotype.'),('DIP bony enlargement with brief use-related stiffness','This favors hand osteoarthritis.'),('Acute podagra with needle-shaped negatively birefringent crystals','This establishes a urate crystal pattern rather than SpA.')],
 'Classify the musculoskeletal phenotype before choosing therapy','**Peripheral SpA commonly includes asymmetric lower-limb synovitis and insertional inflammation.**',['Dactylitis, psoriasis, preceding infection, IBD or uveitis may provide additional clues.','The phenotype is not limited to one joint pattern and can overlap with axial disease.'], '**Investigate hot joints and alternative diagnoses when indicated.**',['A joint aspirate can identify crystals or support infection assessment.','Use the dominant disease domains to guide treatment selection.'],[['Peripheral SpA','Oligoarthritis, enthesitis or dactylitis'],['RA','Often symmetric small-joint synovitis'],['Crystal arthritis','Synovial crystal identification']],[P,K])

if __name__=='__main__':finalize('Rheumatology',2,'Spondyloarthritis','rheum-spa',rows,28)
